CREATE TABLE cmdb_ire_quality_config (tenant_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, enabled BOOLEAN NOT NULL DEFAULT TRUE, schedule_hours SMALLINT UNSIGNED NOT NULL DEFAULT 24, stale_days SMALLINT UNSIGNED NOT NULL DEFAULT 90, required_fields JSON NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, updated_by BIGINT UNSIGNED NOT NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), next_run_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT cmdb_ire_quality_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, CONSTRAINT cmdb_ire_quality_user FOREIGN KEY(updated_by) REFERENCES users(id), CONSTRAINT cmdb_ire_quality_interval CHECK(schedule_hours BETWEEN 1 AND 720), CONSTRAINT cmdb_ire_quality_staleness CHECK(stale_days BETWEEN 1 AND 3650)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
